// Development-only actual BinaryReader/BinaryWriter API traces. No Pascal compiler.
using System;using System.IO;using System.Text;using System.Collections.Generic;
class BinaryCodecReference{
 static StreamWriter log;static MemoryStream stream;static BinaryWriter writer;static BinaryReader reader;static int id,cp,rows;static uint random=0x73ab1c95;
 static uint Next(){unchecked{random=random*1664525+1013904223;return random;}}
 static string Hex(byte[] b){return b.Length==0?"-":BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
 static string U(string s){if(s.Length==0)return "-";var r=new StringBuilder();foreach(char c in s)r.Append(((int)c).ToString("x4"));return r.ToString();}
 static void Row(string op,string type,string input,string outcome,string output){log.WriteLine(id+"\t"+cp+"\t"+op+"\t"+type+"\t"+input+"\t"+outcome+"\t"+output+"\t"+stream.Position);++rows;}
 static void Start(Encoding e,byte[] data,bool write){++id;cp=e.CodePage;if(stream!=null)stream.Dispose();stream=new MemoryStream();stream.Write(data,0,data.Length);stream.Position=0;if(write)writer=new BinaryWriter(stream,e,true);else reader=new BinaryReader(stream,e,true);Row(write?"writer":"reader","-",Hex(data),"ok","-");}
 static void Write(string type,object value){stream.Position=0;stream.SetLength(0);string input=type=="char"?((int)(char)value).ToString("x4"):type=="string"?U((string)value):Hex(Bits(type,value));string error="ok";try{switch(type){case "bool":writer.Write((bool)value);break;case "byte":writer.Write((byte)value);break;case "sbyte":writer.Write((sbyte)value);break;case "word":writer.Write((ushort)value);break;case "smallint":writer.Write((short)value);break;case "integer":writer.Write((int)value);break;case "longword":writer.Write((uint)value);break;case "int64":writer.Write((long)value);break;case "uint64":writer.Write((ulong)value);break;case "single":writer.Write((float)value);break;case "real":writer.Write((double)value);break;case "char":writer.Write((char)value);break;case "string":writer.Write((string)value);break;}}catch(Exception e){error=e.GetType().Name;}Row("write",type,input,error,Hex(stream.ToArray()));}
 static byte[] Bits(string type,object value){switch(type){case "bool":return new[]{(byte)((bool)value?1:0)};case "byte":return new[]{(byte)value};case "sbyte":return new[]{unchecked((byte)(sbyte)value)};case "word":return BitConverter.GetBytes((ushort)value);case "smallint":return BitConverter.GetBytes((short)value);case "integer":return BitConverter.GetBytes((int)value);case "longword":return BitConverter.GetBytes((uint)value);case "int64":return BitConverter.GetBytes((long)value);case "uint64":return BitConverter.GetBytes((ulong)value);case "single":return BitConverter.GetBytes((float)value);case "real":return BitConverter.GetBytes((double)value);default:throw new Exception("Unknown scalar");}}
 static void Read(string type){string error="ok",output="-";try{object value;switch(type){case "bool":value=reader.ReadBoolean();break;case "byte":value=reader.ReadByte();break;case "sbyte":value=reader.ReadSByte();break;case "word":value=reader.ReadUInt16();break;case "smallint":value=reader.ReadInt16();break;case "integer":value=reader.ReadInt32();break;case "longword":value=reader.ReadUInt32();break;case "int64":value=reader.ReadInt64();break;case "uint64":value=reader.ReadUInt64();break;case "single":value=reader.ReadSingle();break;case "real":value=reader.ReadDouble();break;case "char":value=reader.ReadChar();break;case "string":value=reader.ReadString();break;default:throw new Exception("Unknown read");}output=type=="char"?((int)(char)value).ToString("x4"):type=="string"?U((string)value):Hex(Bits(type,value));}catch(Exception e){error=e.GetType().Name;}Row("read",type,"-",error,output);}
 static void Seek(int position){stream.Position=position;Row("seek","-",position.ToString(),"ok","-");}
 static void Main(string[] args){BinaryOracle.Setup(args.Length>2&&args[2]=="modern");using(log=new StreamWriter(args[0],false,new UTF8Encoding(false))){log.WriteLine("# session\tcode_page\toperation\ttype\tinput\toutcome\toutput\tposition");var basic=Encoding.GetEncoding(1251);Start(basic,new byte[0],true);Write("bool",false);Write("bool",true);for(int n=0;n<65536;++n){Write("word",(ushort)n);Write("smallint",unchecked((short)n));if(n<256){Write("byte",(byte)n);Write("sbyte",unchecked((sbyte)n));}}
 for(int n=0;n<1024;++n){uint a=Next(),b=Next();ulong wide=((ulong)a<<32)|b;Write("integer",unchecked((int)a));Write("longword",a);Write("int64",unchecked((long)wide));Write("uint64",wide);Write("single",BitConverter.ToSingle(BitConverter.GetBytes(a),0));Write("real",BitConverter.Int64BitsToDouble(unchecked((long)wide)));}
 foreach(string type in new[]{"bool","byte","sbyte","word","smallint","integer","longword","int64","uint64","single","real"})for(int size=0;size<=12;++size){var data=new byte[size];for(int k=0;k<size;++k)data[k]=(byte)Next();Start(basic,data,false);Read(type);Read(type);}
 foreach(int value in new[]{0,1,2,127,128,255}){Start(basic,new[]{(byte)value},false);Read("bool");}
 foreach(int page in BinaryOracle.Pages(args[1])){var e=BinaryOracle.Get(page);Start(e,new byte[0],true);foreach(char c in new[]{'A','日','+','क','\u094d','\u200c','\u200d','\ud83d','\ude00'})Write("char",c);foreach(string s in new[]{"","A","日","日+","क्","\u200c","\u200d","\ud83d","\ude00","🌍"})Write("string",s);
 foreach(int length in new[]{1,19,32,42,51,85,127,128,255,256,257,1023,1024}){Write("char",'\u094d');Write("string","\u200c"+new string('A',length)+"日🌍\ud83d");Write("char",'\u200c');}
 var inputs=new List<byte[]> {new byte[0],e.GetBytes("日"),e.GetBytes("🌍"),e.GetBytes("क्"),new byte[]{0xc2},new byte[]{0xf0,0x9f,0x8c,0x8d},new byte[]{43,90,101},new byte[]{43,50,65,65,45}};for(int n=0;n<256;++n)inputs.Add(new[]{(byte)n});foreach(var data in inputs){Start(e,data,false);Read("char");Read("char");Seek(0);Read("char");Seek(0);Read("string");}
 foreach(var data in new[]{new byte[]{128,128,128,128,128,0},new byte[]{255,255,255,255,15},new byte[]{128,128,128,128,16},new byte[]{255,255,255,255,7},new byte[]{1,0xc2,1,0xa0},new byte[]{3,43,90,101,1,85,45},new byte[]{1,27,2,36,66},new byte[]{3,239,66,179,1,232}}){Start(e,data,false);Read("string");Read("string");Seek(0);Read("char");}
 }
 }if(stream!=null)stream.Dispose();Console.WriteLine(rows+" actual binary codec traces");}
}